import numpy as np,json
p=np.load('lin2.npy'); A=p[:9].reshape(3,3); B=p[9:18].reshape(3,3); C=p[18:24].reshape(2,3)
params={}
for i in range(3):
    for j in range(3): params[f'a{i}{j}']=float(A[i,j]); params[f'b{i}{j}']=float(B[i,j])
for i in range(2):
    for j in range(3): params[f'c{i}{j}']=float(C[i,j])
u=['(V-V0)','(Vset-V0)','(theta-theta0)']
states={}
for i in range(3):
    rhs=' + '.join([f"a{i}{j}*x{j}" for j in range(3)]+[f"b{i}{j}*{u[j]}" for j in range(3)])
    states[f'x{i}']={'rhs':rhs,'init':'0.0'}
outs={'P':'P0 + '+' + '.join([f"c0{j}*x{j}" for j in range(3)]),
      'Q':'Q0 + '+' + '.join([f"c1{j}*x{j}" for j in range(3)])}
outs={k:v.replace('+ +','+') for k,v in outs.items()}
sub={'params':params,'defs':{},'states':states,'outputs':outs}
json.dump(sub,open('submission.json','w'),indent=1)
print(outs)

